param([Parameter(Mandatory = $true)][string]$TrialReceiptPath,[Parameter(Mandatory = $true)][string]$VerifierId,[Parameter(Mandatory = $true)][string]$VerificationEvidenceRef,[Parameter(Mandatory = $true)][ValidateSet('passed','failed')][string]$Result,[switch]$PassThru)
$ErrorActionPreference='Stop';function Emit([object]$v,[int]$c=0){if($PassThru){$v|ConvertTo-Json -Depth 12}else{$v|Format-List};if($c-ne 0){exit $c}};try{$trial=Get-Content -LiteralPath ((Resolve-Path -LiteralPath $TrialReceiptPath -ErrorAction Stop).Path)-Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='trial_receipt_invalid';verification_written=$false}) 1};if([string]$trial.result-ne'passed'){Emit ([ordered]@{status='blocked';reason='passed_trial_required';verification_written=$false}) 1};if($VerificationEvidenceRef-notmatch'^(?:[a-z][a-z0-9+.-]*://|sha256:)[^\s]+$'){Emit ([ordered]@{status='blocked';reason='verification_evidence_required';verification_written=$false}) 1};$r=[ordered]@{schema_version=1;verification_id='verification-'+[Guid]::NewGuid().ToString('n');trial_id=[string]$trial.trial_id;passport_id=[string]$trial.passport_id;verifier_id=$VerifierId;evidence_ref=$VerificationEvidenceRef;result=$Result;independent=$true;production_authority=$false;created_at=[DateTime]::UtcNow.ToString('o')};$path=[IO.Path]::ChangeExtension($TrialReceiptPath,'.verification.json');[IO.File]::WriteAllText($path,($r|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Emit ([ordered]@{status='verified';verification_path=$path;result=$Result;production_authority=$false})
